{
  "key": "gh-55",
  "fields": {
    "summary": "[ci-heal] run-name contract: group token must lead the run-name",
    "description": "**Run-name contract** (self-heal observability): for every parameterized factory-owned workflow, the `run-name` FIRST token must be the stable group key - it must contain the dispatch parameter (`inputs.*` / issue number) and must NOT contain run-varying values (`run_id`, `run_number`, timestamps, SHAs).\n\n**Non-conforming:** Geo Probe\n\n**Fix:** restructure the `run-name` so the group token leads, e.g. `run-name: gh- - dev` for an issue-parameterized leg. Plain (non-parameterized) workflows may use the workflow name as the token.\n\n**Why:** the self-heal legs-health detector groups runs by the first run-name token; without a leading group token a chronically failing parameter is invisible (interleaved greens reset raw streaks). The fix must ONLY adjust `run-name` - no behavioral changes. Use `Closes #<this issue>`."
  }
}

import 'dart:io';
import 'package:test/test.dart';

/// Run-name contract for the parameterized factory-owned workflows
/// ([ci-heal] self-heal observability).
///
/// The self-heal legs-health detector groups runs by the FIRST token of the
/// run-name (`displayTitle | split(" ")[0]`), so for a parameterized
/// workflow the run-name must OPEN with the stable group key
/// (`gh-<issue>` / `pr-<pr>`) and must not carry run-varying values.
/// The tests mirror the two consumers of the run-name in
/// `.github/workflows/ci-heal.yml`:
///   * the "Run-name contract scan" step (first quoted literal heuristic), and
///   * the "Legs health" step (grouping by the first space-delimited token),
/// plus the dedupe gate regex in `ai-teammate.yml` itself.
const workflowPath = '.github/workflows/ai-teammate.yml';

/// The folded (`>-`) run-name scalar unfolded the way YAML folds:
/// continuation lines joined with single spaces.
String runNameValue(String yaml) {
  final lines = yaml.split('\n');
  final start = lines.indexWhere((l) => l.startsWith('run-name:'));
  if (start < 0) return '';
  final block = lines
      .sublist(start + 1)
      .takeWhile((l) => l.trim().isEmpty || l.startsWith(' '))
      .toList();
  return block.map((l) => l.trim()).join(' ');
}

/// Replicates ci-heal's "group hidden" heuristic: the first quoted literal,
/// cut at the first `{`, whitespace-stripped. Non-empty = a literal prefix
/// hides the group token.
String scannerPrefix(String runName) {
  final firstQuoted = RegExp("'[^']*'").firstMatch(runName)?.group(0);
  if (firstQuoted == null) return '';
  final literal = firstQuoted.replaceAll("'", '');
  final brace = literal.indexOf('{');
  return (brace < 0 ? literal : literal.substring(0, brace))
      .replaceAll(RegExp(r'\s'), '');
}

void main() {
  final yaml = File(workflowPath).readAsStringSync();
  final runName = runNameValue(yaml);

  group('run-name contract (ci-heal observability)', () {
    test('parameterized workflow declares a run-name', () {
      expect(yaml, contains('issues:'),
          reason: 'the issues trigger makes the workflow parameterized');
      expect(yaml, contains('inputs:'),
          reason: 'workflow_dispatch inputs make the workflow parameterized');
      expect(runName, isNotEmpty);
    });

    test('run-name carries no run-varying values', () {
      final noise = RegExp(r'run_id|run_number|timestamp|head_sha');
      expect(noise.allMatches(runName), isEmpty);
    });

    test('ci-heal scan: no literal prefix before the leading expression', () {
      expect(scannerPrefix(runName), isEmpty,
          reason: 'ci-heal flags "parameterized, first run-name token is '
              'literal ..." — the group key must be resolved by the leading '
              'expression itself, not prefixed by a literal');
    });

    test('leading expression resolves the anchor before any leg marker', () {
      expect(runName.startsWith(r'${'), isTrue,
          reason: 'the value must open with the group-key expression, '
              'not a literal');
      final ghAnchor = runName.indexOf("format('gh-{0}'");
      final prAnchor = runName.indexOf("format('pr-{0}'");
      final dispatchLeg = runName.indexOf("'workflow_dispatch'");
      final emojis = ['▶', '✅', '🔧', '🔍', '⚒']
          .map(runName.indexOf)
          .where((i) => i >= 0);
      expect(ghAnchor, greaterThan(-1), reason: 'gh- anchor token missing');
      expect(prAnchor, greaterThan(-1), reason: 'pr- anchor token missing');
      expect(ghAnchor, lessThan(dispatchLeg),
          reason: 'group key must be produced before the dispatch leg branch');
      for (final e in emojis) {
        expect(ghAnchor, lessThan(e),
            reason: 'group key must lead every leg/emoji literal');
      }
    });
  });

  group('legs-health grouping (displayTitle split on first space)', () {
    String groupKey(String displayTitle) => displayTitle.split(' ').first;

    test('conforming titles group runs per parameter (2+ runs per group)', () {
      final titles = [
        'gh-23 · ⚒️ dev: Fix the run-name',
        'gh-23 · ⚒️ dev: Follow-up tweak',
        'gh-24 · ⚒️ dev: Unrelated issue',
        'gh-23 · 🔍 review: Re-review',
        'pr-45 · ▶ review (SM)',
      ];
      expect(titles.map(groupKey).toSet(), hasLength(3),
          reason: 'one stable key per parameter: gh-23, gh-24, pr-45');
      expect(titles.where((t) => groupKey(t) == 'gh-23'), hasLength(3));
    });

    test('legacy titles (leg first) collapsed by leg, hiding the parameter',
        () {
      // The regression this contract prevents: every parameter shared one
      // group key, so interleaved greens reset raw streaks.
      final legacy = ['⚒️ dev · gh-23: A', '⚒️ dev · gh-24: B'];
      expect(legacy.map(groupKey).toSet(), hasLength(1));
    });
  });

  group('dedupe-gate compatibility', () {
    test('anchor token matches the gate regex in the leading position', () {
      RegExp gate(String t) => RegExp('(^|[^0-9])' + t + r'([^0-9]|$)');
      expect(gate('gh-23').hasMatch('gh-23 · ⚒️ dev: Fix the run-name'), isTrue);
      expect(gate('pr-45').hasMatch('pr-45 · ▶ review (SM)'), isTrue);
      expect(gate('gh-24').hasMatch('gh-23 · ⚒️ dev: Fix the run-name'),
          isFalse);
    });
  });
}

import 'dart:io';
import 'package:test/test.dart';

/// Shared-prep contract for the CI lanes (gh-41 regression).
///
/// PR #40 ("prep: simplify stamp write") introduced
/// `tool/prepare.sh` — the "Toolchain stamp (shared prep)" step. The script
/// shells out to `dart` and redirects into `.dart_tool/toolchain.txt`, but
/// on a fresh checkout NEITHER precondition holds before the lane's later
/// steps run: the Dart SDK is only installed by `dart-lang/setup-dart@v1`,
/// and the `.dart_tool/` directory is only created by `dart pub get`.
/// Both lanes ran the stamp FIRST, so every run died in the prep step
/// (gh-41: exit 127 `dart: command not found`, then exit 1
/// `.dart_tool/toolchain.txt: No such file or directory` once the older
/// failure mode was read as the cause).
///
/// The contract, mirrored from the healthy `ci-params.yml` lane:
///   1. every lane that stamps installs the Dart SDK BEFORE the stamp step;
///   2. the script creates `.dart_tool/` itself and works on a fresh
///      checkout (no `.dart_tool/`, `dart pub get` not run yet);
///   3. the script is idempotent (re-runs must stay green).

/// Lanes that run the shared prep stamp. `ci.yml` is the PR validation
/// lane (dispatched on PR heads as required check `test`), `ci-extra.yml`
/// runs on pushes to main — leaving either broken blocks the other's fixes.
const ciLanes = [
  '.github/workflows/ci.yml',
  '.github/workflows/ci-extra.yml',
];

final prepScriptPath = 'tool/prepare.sh';

void main() {
  group('CI lane step order (gh-41: stamp ran before setup-dart)', () {
    for (final lane in ciLanes) {
      test('$lane installs Dart before the shared prep stamp', () {
        final yaml = File(lane).readAsStringSync();
        final setupDart = yaml.indexOf('uses: dart-lang/setup-dart@v1');
        final prep = yaml.indexOf('run: bash tool/prepare.sh');
        expect(setupDart, greaterThan(-1),
            reason: '$lane must declare the Dart SDK install step');
        expect(prep, greaterThan(-1),
            reason: '$lane must declare the shared prep stamp step');
        expect(setupDart, lessThan(prep),
            reason: 'the stamp shells out to `dart` — the SDK must be on '
                'PATH first, or the step dies (gh-41 exit 127)');
      });
    }
  });

  group('tool/prepare.sh (shared prep)', () {
    test('creates .dart_tool before redirecting the stamp into it', () {
      final script = File(prepScriptPath).readAsStringSync();
      final mkdir = script.indexOf('mkdir -p .dart_tool');
      final redirect = script.indexOf('.dart_tool/toolchain.txt');
      expect(mkdir, greaterThan(-1),
          reason: 'on a fresh checkout .dart_tool/ does not exist yet '
              '(dart pub get runs later) — the bare redirect fails with '
              'exit 1: No such file or directory (gh-41)');
      expect(redirect, greaterThan(-1));
      expect(mkdir, lessThan(redirect),
          reason: 'bash sets up redirections before running the command, '
              'so the directory must exist before the redirect line');
    });

    test('runs green on a fresh checkout (no .dart_tool, no pub get)',
        () async {
      final sandbox =
          await Directory.systemTemp.createTemp('prep_contract_fresh-');
      try {
        final result = await Process.run(
          'bash',
          [File(prepScriptPath).absolute.path],
          workingDirectory: sandbox.path,
        );
        expect(result.exitCode, 0,
            reason: 'the CI stamp step must survive a fresh checkout');
        final stamp = File('${sandbox.path}/.dart_tool/toolchain.txt');
        expect(stamp.existsSync(), isTrue, reason: 'stamp file must exist');
        expect(stamp.readAsStringSync(), contains('Dart SDK version'),
            reason: 'the stamp records which Dart built the workspace');
        expect(result.stderr, isEmpty);
      } finally {
        sandbox.deleteSync(recursive: true);
      }
    });

    test('is idempotent — a second run in the same workspace stays green',
        () async {
      final sandbox =
          await Directory.systemTemp.createTemp('prep_contract_rerun-');
      try {
        final scriptPath = File(prepScriptPath).absolute.path;
        final first = await Process.run('bash', [scriptPath],
            workingDirectory: sandbox.path);
        expect(first.exitCode, 0);
        final second = await Process.run('bash', [scriptPath],
            workingDirectory: sandbox.path);
        expect(second.exitCode, 0,
            reason: 'mkdir -p and the overwrite must both be re-runnable');
      } finally {
        sandbox.deleteSync(recursive: true);
      }
    });
  });
}

